#!/usr/bin/env python3
# In a notebook, do not edit this file. It is generic - the template's, listed
# in .claude/notebook/manifest.txt - and the update skill replaces it; the
# notebook's pre-commit hook refuses a commit that changes it. To extend:
#   - a setting or an audit rule: .scripts/notebook_config.py
#   - an operation or a check of the notebook's own: a script of its own in
#     .scripts/ that imports this one, never a copy of it
#   - a rule for one type: that type's declaration in Types/
#   - a fix every notebook needs: ask the template for it, with an issue -
#     .claude/notebook/requests.md
# The whole table: .claude/notebook/upstream.md, "The outlets".
"""Check that this vault stays legal Obsidian.

It is an Obsidian vault on Obsidian Sync, so names and links have to obey
Obsidian's rules, not just the filesystem's. Three checks, and the first
two are absolute - a hit is always a defect:

  1. Filenames: no " * ? < > : | \\ / [ ] # ^ and no name ending in a
     period or a space. macOS and git accept some of these; Sync rejects
     them and Windows cannot store them.
  2. Link targets: the same characters inside [[...]]. A slash is the worst
     of them, because Obsidian reads it as a folder path, so [[A/b]] looks
     like a working link and silently points at a page that isn't there.
  3. Unresolved links. A dangling link is legal here - it means "named,
     not yet filed" - so the absolute list is informational, and --since
     reports only links that STOPPED resolving, which needs no allowlist.

Obsidian itself is the authority on whether a link resolves: the running
app exposes app.metadataCache.unresolvedLinks and its own resolver. The parser in this file is a
fallback for when the app is not running, and the absolute check compares
the two and complains if they disagree, because a silently wrong scanner
is worse than no scanner.

A title may legitimately contain a character its filename cannot: the page
whose title contains a colon has to take a sanitized filename.
So the H1 is allowed to differ from the filename and is not checked.

  vault_check.py                  all three checks
  vault_check.py --since HEAD     ... with (3) limited to new breakage
  vault_check.py --check "A" "B"  do these names resolve as link targets?
  vault_check.py --names          only the name and link-target checks

Exit status is 0 when there is nothing to report, 1 when there is.
"""

import argparse
import os
import re
import shutil
import subprocess
import sys

import os

# `python3 -I` isolates sys.path, which drops this script's own directory -
# so the config beside it is not importable without putting it back.
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import notebook_config

# Derived from this file's location, never hardcoded: a hardcoded path lets
# a script run from one vault quietly read or edit another.
VAULT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
# The notes are the vault root, so there is no prefix to match on.

SKIP_DIRS = {".git", ".obsidian", ".claude", "__pycache__"}
# Pages a tool does not own (NOT_OURS): documentation about the notes may
# hold deliberate examples of broken syntax ([[A/b]], [[Alias]]) that these
# checks would otherwise flag.
SKIP_FILES = set(notebook_config.NOT_OURS)

OBSIDIAN = shutil.which("obsidian")


def app_is_this_vault():
    """Whether the running app's vault of this folder's name is this folder.
    The CLI finds a vault by its name alone, so a clone or a second checkout
    with the same folder name would otherwise be answered - or written to -
    by the other one."""
    global _THIS_VAULT
    if _THIS_VAULT is None:
        try:
            r = subprocess.run([OBSIDIAN, f"vault={os.path.basename(VAULT)}", "eval",
                                "code=app.vault.adapter.basePath"],
                               capture_output=True, text=True, timeout=20)
            out = r.stdout.strip()
            _THIS_VAULT = (r.returncode == 0 and out.startswith("=>")
                           and os.path.realpath(out[2:].strip()) == os.path.realpath(VAULT))
        except (OSError, subprocess.SubprocessError):
            _THIS_VAULT = False
    return _THIS_VAULT

_THIS_VAULT = None

ILLEGAL_NAME = set('"*?<>:|\\/[]#^')
ILLEGAL_TARGET = set('"*?<>:|\\[]^')  # '/' handled separately: it reads as a path

# [[target]] / [[target|alias]] / [[target\|alias]] / [[target#anchor]] / ![[embed]]
LINK = re.compile(r"\[\[([^\[\]|#]+?)(?:\\?\|[^\[\]]*)?(?:#[^\[\]|]*)?\]\]")

ATTACHMENT_EXT = {".png", ".jpg", ".jpeg", ".gif", ".webp", ".svg", ".pdf", ".base", ".canvas"}


def frontmatter_aliases(text):
    m = re.match(r"---\n(.*?)\n---", text, re.S)
    if not m:
        return []
    fm, out = m.group(1), []
    block = re.search(r"^aliases:[ \t]*\n((?:[ \t]*-[ \t]*\S.*\n?)+)", fm + "\n", re.M)
    if block:
        for line in block.group(1).splitlines():
            a = line.strip().lstrip("-").strip().strip("\"'")
            if a:
                out.append(a)
    inline = re.search(r"^aliases:[ \t]*\[(.*?)\]", fm, re.M)
    if inline:
        out += [a.strip().strip("\"'") for a in inline.group(1).split(",") if a.strip()]
    return out


def walk_vault():
    """Every path in the vault worth checking, vault-relative."""
    for dirpath, dirnames, filenames in os.walk(VAULT):
        dirnames[:] = [d for d in dirnames if d not in SKIP_DIRS and not d.startswith(".")]
        for name in list(dirnames) + filenames:
            if name == ".DS_Store":
                continue
            yield os.path.relpath(os.path.join(dirpath, name), VAULT)


def read_tree(ref=None):
    """Map vault-relative path -> text, from a git ref or the working tree."""
    files = {}
    if ref:
        listing = subprocess.run(
            ["git", "-C", VAULT, "ls-tree", "-r", "--name-only", ref],
            capture_output=True, text=True, check=True,
        ).stdout.splitlines()
        for p in listing:
            ext = os.path.splitext(p)[1].lower()
            if ext in ATTACHMENT_EXT:
                files[p] = ""
            elif p.endswith(".md"):
                blob = subprocess.run(["git", "-C", VAULT, "show", f"{ref}:{p}"],
                                      capture_output=True, text=True)
                if blob.returncode == 0:
                    files[p] = blob.stdout
        return files

    for rel in walk_vault():
        full = os.path.join(VAULT, rel)
        if not os.path.isfile(full):
            continue
        ext = os.path.splitext(rel)[1].lower()
        if ext in ATTACHMENT_EXT:
            files[rel] = ""
        elif rel.endswith(".md"):
            with open(full, encoding="utf-8", errors="replace") as fh:
                files[rel] = fh.read()
    return files


def check_names():
    """(path, reason) for every name Obsidian Sync would reject."""
    out = []
    for rel in walk_vault():
        name = os.path.basename(rel)
        stem = name[:-3] if name.endswith(".md") else name
        hits = sorted(ILLEGAL_NAME & set(stem))
        if hits:
            out.append((rel, "illegal character " + " ".join(repr(c) for c in hits)))
        elif stem.endswith("."):
            out.append((rel, "name ends in a period"))
        elif stem.endswith(" "):
            out.append((rel, "name ends in a space"))
    return out


def uncoded(text):
    """The text with code - fenced blocks and inline spans - blanked out, line
    breaks kept so line numbers still hold. Obsidian indexes no link inside
    code, so neither does this: a declaration showing `[[<a placeholder>]]`
    is documenting a link, not making one."""
    blank = lambda m: re.sub(r"[^\n]", " ", m.group(0))
    text = re.sub(r"^(```|~~~).*?^\1[ \t]*$", blank, text, flags=re.M | re.S)
    return re.sub(r"`[^`\n]+`", blank, text)


def check_targets(files):
    """(path, line, target, reason) for link targets Obsidian can't resolve literally."""
    out = []
    for rel, text in sorted(files.items()):
        if not rel.endswith(".md") or os.path.basename(rel) in SKIP_FILES:
            continue
        for m in LINK.finditer(uncoded(text)):
            target = m.group(1).strip()
            line = text[: m.start()].count("\n") + 1
            if "/" in target:
                # A slash is only a bug when it is part of a NAME: Obsidian
                # reads [[A/b]] as a vault path, so such a link dangles while
                # looking fine. But a slash that really is a path to a file
                # that exists resolves, and it is the only way to write an
                # unambiguous link when two folders hold the same basename -
                # a thing and the problem it poses, say, which the contract
                # wants as separate pages under one name. Verified
                # against the running app on 2026-10-21: such a link resolves
                # and stays out of unresolvedLinks. So flag only a miss.
                if target + ".md" not in files:
                    out.append((rel, line, target,
                                "slash target does not exist - "
                                "reads as a folder path"))
            else:
                hits = sorted(ILLEGAL_TARGET & set(target))
                if hits:
                    out.append((rel, line, target,
                                "illegal character " + " ".join(repr(c) for c in hits)))
    return out


def broken_frontmatter(files):
    """Pages that open with '---' but whose frontmatter Obsidian cannot parse.

    This is invisible to every other check here and to the app's own UI: when
    the YAML is malformed the WHOLE block is dropped, so type:, aliases: and
    source: all vanish at once while the page still looks fine. In the
    notebook this grew from, it was found on three pages, one of them a
    person's: the page had no type: as far as Obsidian was concerned, so it
    was missing from its type's view and its four aliases never reached the
    quick switcher.

    The cause each time was quoting: a plain scalar that merely STARTS with a
    quote ('- "<Title>" clipping'), or a double-quoted scalar with
    unescaped inner quotes ('- "<Place> ("<Name>")"'). Both are
    legal-looking and neither is valid YAML. Single-quote the value instead -
    single-quoted YAML permits inner double quotes.

    Obsidian is the authority, so this asks the app and returns None when it
    is unreachable rather than guessing with a second YAML parser.
    """
    if not OBSIDIAN or not app_is_this_vault():
        return None
    import json
    code = ("JSON.stringify(app.vault.getMarkdownFiles()"
            ".filter(f => !app.metadataCache.getFileCache(f)?.frontmatter)"
            ".map(f => f.path))")
    try:
        r = subprocess.run([OBSIDIAN, f"vault={os.path.basename(VAULT)}",
                            "eval", f"code={code}"],
                           capture_output=True, text=True, timeout=25)
        raw = r.stdout.strip()
        if raw.startswith("=>"):
            raw = raw[2:].strip()
        paths = json.loads(raw)
    except Exception:
        return None
    # No frontmatter at all is fine (plain notes, generated pages). Only a page that
    # opens the block and then fails to parse is a defect.
    return [p for p in paths
            if p in files and files[p].startswith("---\n")]


def unresolved_from_obsidian():
    """Ask the running Obsidian for its unresolved-link map.

    Returns (target, path, None) rows, or None if the app is not reachable.
    This is authoritative: it is the same index the app's own backlinks
    pane uses, so it understands aliases and Obsidian's link syntax.
    """
    if not OBSIDIAN or not app_is_this_vault():
        return None
    # Name the vault explicitly. Without vault=, the CLI answers for whichever
    # vault the app has active, so a check run here can silently report
    # another vault's link graph.
    code = "JSON.stringify(app.metadataCache.unresolvedLinks)"
    try:
        r = subprocess.run([OBSIDIAN, f"vault={os.path.basename(VAULT)}",
                            "eval", f"code={code}"],
                           capture_output=True, text=True, timeout=25)
    except (subprocess.TimeoutExpired, OSError):
        return None
    out = r.stdout.strip()
    if r.returncode != 0 or not out.startswith("=>"):
        return None
    import json
    try:
        data = json.loads(out[2:].strip())
    except ValueError:
        return None
    rows = []
    for path, targets in data.items():
        if os.path.basename(path) in SKIP_FILES:
            continue
        for target, count in targets.items():
            for _ in range(max(1, count)):
                rows.append((target, path, None))
    return rows


def resolvable(files):
    """Every name a wikilink actually resolves to: basenames and attachments.

    Aliases are deliberately NOT included. Verified against Obsidian
    2026-10-21: a bare [[Alias]] does not resolve even when the alias is in
    the target's frontmatter - getFirstLinkpathDest returns null and the
    link lands in unresolvedLinks. Aliases feed the quick switcher and
    autocomplete, which inserts the piped form [[Real name|Alias]]. Adding
    them here made this parser more permissive than Obsidian, so it called
    genuinely broken links fine.
    """
    names = {notebook_config.HUB[:-3].lower()}
    for rel, text in files.items():
        base = os.path.basename(rel)
        names.add(base.lower())
        if base.endswith(".md"):
            names.add(base[:-3].lower())
        # A vault-root-relative path resolves as well as a bare basename,
        # and it is the ONLY unambiguous way to link one of two pages that
        # share a basename, as two folders may on purpose. Without these the
        # parser called every correct path link broken - in the notebook this
        # grew from, it cried wolf on nine good links.
        names.add(rel.lower())
        if rel.endswith(".md"):
            names.add(rel[:-3].lower())
    return names


def alias_index(files):
    """alias (lowercased) -> the page that lists it, for better diagnostics."""
    out = {}
    for rel, text in files.items():
        if rel.endswith(".md"):
            for a in frontmatter_aliases(text):
                out.setdefault(a.lower(), os.path.basename(rel)[:-3])
    return out


def unresolved(files):
    """(target, path, line) for every link that does not resolve."""
    names, out = resolvable(files), []
    for rel, text in sorted(files.items()):
        if not rel.endswith(".md") or os.path.basename(rel) in SKIP_FILES:
            continue
        for m in LINK.finditer(uncoded(text)):
            target = m.group(1).strip()
            if target and target.lower() not in names:
                out.append((target, rel, text[: m.start()].count("\n") + 1))
    return out


def rel_notes(p):
    return p


def main():
    ap = argparse.ArgumentParser(description=__doc__,
                                 formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--since", metavar="REF",
                    help="limit the unresolved-link check to breakage new since REF")
    ap.add_argument("--check", nargs="+", metavar="NAME",
                    help="report which of these names do not resolve")
    ap.add_argument("--names", action="store_true",
                    help="only the filename and link-target checks")
    args = ap.parse_args()

    now = read_tree()

    if args.check:
        names, aliases = resolvable(now), alias_index(now)
        missing = [n for n in args.check if n.lower() not in names]
        for n in missing:
            owner = aliases.get(n.lower())
            if owner:
                print(f"does not resolve: [[{n}]] - it is an alias of "
                      f"\"{owner}\", and a bare alias link does not resolve. "
                      f"Write [[{owner}|{n}]].")
            else:
                print(f"does not resolve: [[{n}]]")
        if not missing:
            print(f"all {len(args.check)} resolve")
        return 1 if missing else 0

    problems = 0

    bad_names = check_names()
    if bad_names:
        problems += len(bad_names)
        print(f"illegal filenames ({len(bad_names)}) - Obsidian Sync will reject these:")
        for rel, why in bad_names:
            print(f"  {rel}\n      {why}")
    bad_targets = check_targets(now)
    if bad_targets:
        problems += len(bad_targets)
        print(f"illegal link targets ({len(bad_targets)}):")
        for rel, line, target, why in bad_targets:
            print(f"  {rel_notes(rel)}:{line}  [[{target}]]\n      {why}")

    bad_fm = broken_frontmatter(now)
    if bad_fm:
        problems += len(bad_fm)
        print(f"frontmatter Obsidian cannot parse ({len(bad_fm)}) - the WHOLE "
              f"block is dropped, so type:, aliases: and source: all vanish:")
        for rel in bad_fm:
            print(f"  {rel_notes(rel)}\n      check the quoting; single-quote a "
                  f"value containing double quotes")

    if args.names:
        if not problems:
            print("names and link targets: clean")
        return 1 if problems else 0

    current = unresolved(now)
    if args.since:
        try:
            then = read_tree(args.since)
        except subprocess.CalledProcessError:
            print(f"cannot read git ref {args.since!r}", file=sys.stderr)
            return 2
        # Stopped resolving: its target was a page then and is not now - a
        # rename or a deletion. A new link to a page nobody has written yet
        # is "named, not yet filed", which is legal, so it is not counted.
        was = resolvable(then)
        new = [row for row in current if row[0].lower() in was]
        if new:
            problems += len(new)
            print(f"links that stopped resolving since {args.since}:")
            for target, rel, line in new:
                print(f"  [[{target}]]  {rel_notes(rel)}:{line}")
        elif not problems:
            print(f"clean - no links broken since {args.since} "
                  f"({len(current)} dangling: named, not yet filed)")
    else:
        # Obsidian is the authority; the local parser is fallback and canary.
        from_app = unresolved_from_obsidian()
        rows, source = (from_app, "Obsidian") if from_app is not None else (current, "fallback parser")

        if from_app is not None:
            app_keys = sorted({(t, p) for t, p, _ in from_app})
            mine = sorted({(t, p) for t, p, _ in current})
            if app_keys != mine:
                only_app = [k for k in app_keys if k not in set(mine)]
                only_mine = [k for k in mine if k not in set(app_keys)]
                problems += len(only_app) + len(only_mine)
                print("the parser in this file disagrees with Obsidian - fix the parser:")
                for tgt, pth in only_app:
                    print(f"  Obsidian sees unresolved, parser does not: [[{tgt}]] in {rel_notes(pth)}")
                for tgt, pth in only_mine:
                    print(f"  parser sees unresolved, Obsidian does not: [[{tgt}]] in {rel_notes(pth)}")

        if rows:
            by = {}
            for target, rel, line in rows:
                by.setdefault(target, []).append((rel, line))
            print(f"dangling links ({len(rows)} across {len(by)} targets, per {source}) - "
                  f"legal, each means \"named, not yet filed\":")
            for target in sorted(by, key=lambda t: (-len(by[t]), t.lower())):
                print(f"  [[{target}]]  ({len(by[target])})")
                for rel, line in by[target]:
                    print(f"      {rel_notes(rel)}" + (f":{line}" if line else ""))
        elif not problems:
            print(f"clean (links per {source})")

    return 1 if problems else 0


if __name__ == "__main__":
    sys.exit(main())
